def contar_palavras(palavras):
    contagens = {}
    for palavra in palavras:
        contagens[palavra] = contagens.get(palavra, 0) + 1
    return contagens

def media(valores):
    if not valores:
        return 0
    return sum(valores) / len(valores)

def somar_dicionarios(primeiro, segundo):
    resultado = {}
    for dicionario in (primeiro, segundo):
        for chave, valor in dicionario.items():
            resultado[chave] = resultado.get(chave, 0) + valor
    return resultado
